method parse_music(music_string: string) returns (result: seq<int>)
    requires music_string != null
    ensures |result| == CountNotes(music_string)
    ensures forall i :: 0 <= i < |result| ==> (result[i] == NoteDuration(music_string, i))

    // Helper function to count the number of notes in the string
    function CountNotes(music_string: string): int
        reads music_string
        decreases |music_string|
    {
        var count := 0;
        var i := 0;
        while i < |music_string|
            invariant 0 <= count <= |music_string|
            invariant 0 <= i <= |music_string|
        {
            if music_string[i] == 'o' {
                count := count + 1;
                if i + 1 < |music_string| && music_string[i + 1] == ' ' {
                    i := i + 2; // Skip over 'o' and the space
                } else {
                    i := i + 1; // Just skip over 'o'
                }
            } else if music_string[i] == '|' {
                count := count + 1;
                i := i + 1; // Skip over '|'
            } else if music_string[i] == '.' {
                count := count + 1;
                i := i + 2; // Skip over '.|' and the space
            } else {
                i := i + 1; // Skip over spaces or any unexpected characters
            }
        }
        return count;
    }

    // Helper function to get the duration of a note at the given index
    function NoteDuration(music_string: string, index: int): int
        reads music_string
        requires 0 <= index < CountNotes(music_string)
    {
        var i := 0;
        var note_index := 0;

        while note_index < index
            invariant 0 <= note_index <= index
            invariant 0 <= i <= |music_string|
        {
            if music_string[i] == 'o' {
                note_index := note_index + 1;
                if i + 1 < |music_string| && music_string[i + 1] == ' ' {
                    i := i + 2; // Skip over 'o' and the space
                } else {
                    i := i + 1; // Just skip over 'o'
                }
            } else if music_string[i] == '|' {
                note_index := note_index + 1;
                i := i + 1; // Skip over '|'
            } else if music_string[i] == '.' {
                note_index := note_index + 1;
                i := i + 2; // Skip over '.|' and the space
            } else {
                i := i + 1; // Skip over spaces or any unexpected characters
            }
        }

        if music_string[i - 1] == 'o' {
            return 4;
        } else if i >= 2 && music_string[i - 2] == 'o' && music_string[i - 1] == '|' {
            return 2;
        } else if i >= 2 && music_string[i - 2] == '.' && music_string[i - 1] == '|' {
            return 1;
        } else {
            return 0; // This case should not happen if the index is valid
        }
    }
